// Function Pointer Target
int increment(int x) { return x + 1; }

// Adapt Function Pointer to Functor (Wrapper generation)
auto inc_functor = std::ptr_fun(increment);

// Internal Mechanism: std::pointer_to_unary_function instantiated
using Inc_Wrapper = std::pointer_to_unary_function<int, int>;
Inc_Wrapper explicit_functor(increment);

// Usage: Call through operator()
int val = 99;
int result_A = inc_functor(val);     // 100
int result_B = explicit_functor(val); // 100

// Result: A type safe function object (functor) is generated.
